L=(k,d)=>{try{const v=JSON.parse(localStorage.getItem(k));return v==null?d:v}catch(e){return d}},
W=(k,v)=>{if(k in wv){clearTimeout(wt[k]);delete wv[k]}try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}},
Wd=(k,v)=>{wv[k]=v;clearTimeout(wt[k]);wt[k]=setTimeout(()=>{if(k in wv){const x=wv[k];delete wv[k];W(k,x)}},350)},
wFlush=()=>{for(const k in wv){const x=wv[k];delete wv[k];W(k,x)}},
vb=p=>{try{vib&&navigator.vibrate&&navigator.vibrate(p)}catch(e){}};
