const one=async u=>{const h=await c.match(u);if(h){n++;bytes+=+(h.headers.get('content-length')||0);return}
for(let t=0;t<3;t++){try{const r=await fetch(u,{mode:'cors'});if(!r.ok)throw 0;bytes+=+(r.headers.get('content-length')||0);await c.put(u,r);n++;return}catch(e){if(t===2){fail++;return}await new Promise(r=>setTimeout(r,700*(t+1)))}}};
