rdIO=new IntersectionObserver(es=>es.forEach(e=>{const i=+e.target.id.slice(2),ok=e.isIntersecting&&(e.intersectionRatio>=.6||e.intersectionRect.height>=innerHeight*.45);if(ok){if(!rdVis[i])rdVis[i]=Date.now()}else delete rdVis[i]}),{threshold:[0,.3,.6,1]});
