sp=t=>{const D=jd+t-2451545,g=fx(357.529+.98560028*D,360),q=fx(280.459+.98564736*D,360),L=fx(q+1.915*sin(g)+.02*sin(2*g),360),e=23.439-3.6e-7*D;return{dc:Math.asin(sin(e)*sin(L))/R,eq:q/15-fh(Math.atan2(cos(e)*sin(L),cos(L))/R/15)}},
